from pathlib import Path
p = Path("apps/web/e2e/launcher-safe-area.spec.ts"); t = p.read_text()

anchor = "  test('the reserved column is only as wide as the launcher needs', async ({ page }) => {"
new_test = '''  test('the reserved column costs no vertical space', async ({ page }) => {
    // This is the constraint that chose 32px over the launcher's full 56px.
    // Past 32 the card narrows enough to wrap taller, and the extra document
    // height pushes the submit button further below the fold -- which is the
    // second defect #286 reports. A fix for one half of that issue that makes
    // the other half worse is not a fix.
    //
    // Differential rather than absolute: it collapses the reserve to the
    // page's own horizontal padding and compares, so it stays true when the
    // form gains a field and measures the reserve rather than the content.
    await page.setViewportSize({ width: 390, height: 844 })
    await page.goto('/contact', { waitUntil: 'networkidle' })

    const measured = await page.evaluate(() => {
      const submit = [...document.querySelectorAll('button')].find(
        (b) => (b.textContent ?? '').trim() === 'Send Message',
      )
      if (!submit) return null
      const container = submit.closest('div.min-h-screen') as HTMLElement | null
      if (!container) return null

      const withReserve = {
        doc: document.documentElement.scrollHeight,
        submitBottom: Math.round(submit.getBoundingClientRect().bottom),
      }
      const base = getComputedStyle(container).paddingLeft
      const reserved = getComputedStyle(container).paddingRight
      container.style.paddingRight = base
      void container.offsetHeight
      const withoutReserve = {
        doc: document.documentElement.scrollHeight,
        submitBottom: Math.round(submit.getBoundingClientRect().bottom),
      }
      container.style.paddingRight = ''
      return { withReserve, withoutReserve, base, reserved }
    })

    expect(measured, 'the submit button or its page container was not found').not.toBeNull()
    // Vacuity: if the reserve were not applied at this width, both readings
    // would be the same page and the comparison would assert nothing.
    expect(
      measured!.reserved,
      'no reserve is applied at 390 wide, so this comparison is between two identical layouts',
    ).not.toBe(measured!.base)
    expect(
      measured!.withReserve.doc,
      'the reserved column made the document taller',
    ).toBe(measured!.withoutReserve.doc)
    expect(
      measured!.withReserve.submitBottom,
      'the reserved column pushed the primary action further down the page',
    ).toBe(measured!.withoutReserve.submitBottom)
  })

''' + anchor
t = t.replace(anchor, new_test)
p.write_text(t)
print("added")
